      }
    ],
    "lacunas": [],
    "motivo": "Custo da linha base declarado como R$1.650,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_d7254f",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "O crédito do apoio depende do término novo, que não pode ser determinado sem as precedências do projeto."
    ],
    "motivo": "As obrigações fixas são conhecidas, mas o valor recalculado da extensão do apoio depende do término novo.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_d7254f",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "Sem o término novo, não é possível saber se haverá extensão não usada a creditar; a economia pode ser nula ou positiva."
    ],
    "motivo": "O aviso autoriza crédito da extensão não usada, mas sua magnitude depende do término novo.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A linha base declara término D12 e custo de 165000 centavos. O aviso reduz a duração do dossiê de 3 para 1 dia e autoriza recalcular com crédito a extensão do apoio. Como a ficha de precedências mencionada não foi fornecida, não se pode determinar o efeito no marco final nem o crédito correspondente."
}

